input.command:
bash -c '
TOKEN=$(cat /tmp/ivx_owner_token.txt)
echo "=== SUPABASE TABLES (owner API) ==="
curl -s --max-time 15 -H "Authorization: Bearer $TOKEN" "https://api.ivxholding.com/api/ivx/supabase/tables" 2>/dev/null | python3 -c "
import sys,json
d=json.load(sys.stdin)
if isinstance(d, dict):
  print(\"keys=\"+str(list(d.keys())))
  tables = d.get(\"tables\",d.get(\"data\",[]))
  print(\"tables_count=\"+str(len(tables)))
  for t in tables[:20]:
    if isinstance(t, dict):
      print(\"  - \"+str(t.get(\"table_name\",t.get(\"name\",t))))
    else:
      print(\"  - \"+str(t))
elif isinstance(d, list):
  print(\"list_count=\"+str(len(d)))
  for t in d[:20]:
    if isinstance(t, dict):
      print(\"  - \"+str(t.get(\"table_name\",t.get(\"name\",t))))
    else:
      print(\"  - \"+str(t))
" 2>/dev/null
'

