input.command:
bash -c '
TOKEN=$(cat /tmp/ivx_owner_token.txt)
echo "=== SUPABASE TABLES DATA ==="
curl -s --max-time 15 -H "Authorization: Bearer $TOKEN" "https://api.ivxholding.com/api/ivx/supabase/tables" 2>/dev/null | python3 -c "
import sys,json
d=json.load(sys.stdin)
data = d.get(\"data\",{})
if isinstance(data, dict):
  tables = data.get(\"tables\",data.get(\"rows\",[]))
  print(\"tables_type=dict tables_count=\"+str(len(tables)))
  for t in tables[:15]:
    if isinstance(t, dict):
      print(\"  - \"+str(t.get(\"table_name\",t.get(\"name\",t.get(\"tablename\",str(t)[:60])))))
    else:
      print(\"  - \"+str(t))
elif isinstance(data, list):
  print(\"data_list_count=\"+str(len(data)))
  for t in data[:15]:
    if isinstance(t, dict):
      print(\"  - \"+str(t.get(\"table_name\",t.get(\"name\",str(t)[:60]))))
    else:
      print(\"  - \"+str(t))
else:
  print(\"data_type=\"+str(type(data).__name__)+\" data=\"+str(data)[:300])
" 2>/dev/null
'

